// Synthetic sales data for Module 5 (also in docs/materials/module5-sales-synthetic.csv).
// East Q2 revenue is deliberately missing; every other row sells at £25 a unit.
export const SALES_ROWS = [
  { quarter: '2025-Q1', region: 'North', units: 1200, gross: 30000, returns: 900 },
  { quarter: '2025-Q2', region: 'North', units: 1260, gross: 31500, returns: 1100 },
  { quarter: '2025-Q1', region: 'South', units: 950, gross: 23750, returns: 400 },
  { quarter: '2025-Q2', region: 'South', units: 1140, gross: 28500, returns: 450 },
  { quarter: '2025-Q1', region: 'East', units: 1300, gross: 32500, returns: 3900 },
  { quarter: '2025-Q2', region: 'East', units: 1330, gross: null, returns: 4200 },
  { quarter: '2025-Q1', region: 'West', units: 800, gross: 20000, returns: 200 },
  { quarter: '2025-Q2', region: 'West', units: 1000, gross: 25000, returns: 250 },
];
export const REGIONS = ['North', 'South', 'East', 'West'];

// Per-region figures for each definition of "top performer", under a given
// way of handling the missing value ('estimate' = units × £25; 'exclude' =
// leave the blank out). Treating the blank as zero is the error being taught.
export function salesFigures(handling = 'estimate') {
  const out = {};
  for (const region of REGIONS) {
    const rows = SALES_ROWS.filter((r) => r.region === region);
    const value = (r) => (r.gross !== null ? r.gross : handling === 'estimate' ? r.units * 25 : 0);
    const q1 = rows.filter((r) => r.quarter.endsWith('Q1')).reduce((n, r) => n + value(r), 0);
    const q2 = rows.filter((r) => r.quarter.endsWith('Q2')).reduce((n, r) => n + value(r), 0);
    const gross = q1 + q2;
    const returns = rows.reduce((n, r) => n + r.returns, 0);
    out[region] = { gross, net: gross - returns, growth: q1 && q2 ? Math.round(((q2 / q1) - 1) * 1000) / 10 : null };
  }
  return out;
}

